1	// Command contractsentinel is the 智能合约审计与形式化验证流水线 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9	
10		"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
11	)
12	
13	func main() {
14		command := "demo"
15		if len(os.Args) > 1 {
16			command = os.Args[1]
17		}
18		switch command {
19		case "demo":
20			runDemo()
21		case "version":
22			fmt.Println("contractsentinel 0.1.0")
23		case "help", "-h", "--help":
24			usage()
25		case "resolve":
26			runResolve(os.Args[2:])
27		default:
28			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
29			usage()
30			os.Exit(2)
31		}
32	}
33	
34	func usage() {
35		fmt.Println("usage: contractsentinel <command> [arguments]")
36		fmt.Println()
37		fmt.Println("commands:")
38		fmt.Println("  demo                        run the built-in audit demo")
39		fmt.Println("  resolve <config-file>       resolve one JSON request (read from stdin)")
40		fmt.Println("                              against offline routes; no network connections")
41		fmt.Println("  version                     print the version")
42		fmt.Println("  help                        show this help")
43	}
44	
45	func runResolve(args []string) {
46		if len(args) != 1 {
47			fail(contractsentinel.Failure{Code: "invalid_usage",
48				Reason: "usage: contractsentinel resolve <config-file>"})
49		}
50	
51		configData, err := os.ReadFile(args[0])
52		if err != nil {
53			fail(contractsentinel.Failure{Code: "invalid_config",
54				Reason: fmt.Sprintf("cannot read config file %q: %v", args[0], err)})
55		}
56		requestData, err := io.ReadAll(os.Stdin)
57		if err != nil {
58			fail(contractsentinel.Failure{Code: "invalid_request",
59				Reason: fmt.Sprintf("cannot read request from stdin: %v", err)})
60		}
61	
62		cfg, f := contractsentinel.ParseConfig(configData)
63		if f != nil {
64			fail(*f)
65		}
66		req, f := contractsentinel.ParseRequest(requestData)
67		if f != nil {
68			fail(*f)
69		}
70		resolution, f := contractsentinel.Resolve(cfg, req)
71		if f != nil {
72			fail(*f)
73		}
74	
75		// HTML escaping is disabled so a raw query such as "a=1&b=2" is emitted
76		// byte for byte instead of "&".
77		enc := json.NewEncoder(os.Stdout)
78		enc.SetEscapeHTML(false)
79		if err := enc.Encode(resolution); err != nil {
80			fail(contractsentinel.Failure{Code: "internal_error", Reason: err.Error()})
81		}
82	}
83	
84	// fail prints the error as JSON to stderr and exits non-zero; stdout is left
85	// untouched so no partial result is observable on failure.
86	func fail(f contractsentinel.Failure) {
87		enc := json.NewEncoder(os.Stderr)
88		enc.SetEscapeHTML(false)
89		_ = enc.Encode(f)
90		os.Exit(1)
91	}
92	
93	func runDemo() {
