16	// These tests exercise resolve the way a user does: a config file argument,
17	// one JSON request on stdin, and the observable exit status / stdout / stderr
18	// of the whole command. They never open a network connection and do not need
19	// the upstreams to exist, so they reproduce deterministically offline.
20	
21	// helperEnv guards TestHelperProcess: only a child spawned with this variable
22	// set hands its arguments over to the real main; in an ordinary `go test`
23	// run the test is a no-op.
24	const helperEnv = "CONTRACTSENTINEL_HELPER_PROCESS"
25	
26	// TestHelperProcess is the re-executed test binary: arguments after "--"
27	// become the command's own os.Args, then main runs as normal (including its
28	// non-zero os.Exit on failure, which the parent observes via exit status).
29	func TestHelperProcess(t *testing.T) {
30		if os.Getenv(helperEnv) != "1" {
31			return
32		}
33		for i, a := range os.Args {
34			if a == "--" {
35				os.Args = append([]string{os.Args[0]}, os.Args[i+1:]...)
36				break
37			}
38		}
39		main()
40		os.Exit(0)
41	}
